package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamModern43GroupBank3 {
    private const val T = "නූතන බටහිර කලාව හා ශ්‍රී ලංකාවේ '43 කණ්ඩායම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("'උපස්ථිතිවාදය' (Impressionism) යන නම ලැබීමට මුල් වූ ක්ලෝඩ් මොනේගේ 1872 සුප්‍රකට සිතුවම කුමක්ද?", "ඉම්ප්‍රෙෂන්, සන්රයිස් (Impression, Sunrise)", "ස්ටාරි නයිට් (The Starry Night)", "ලේස් ඩෙමොයිසෙල්ස් ඩි ඇවිග්නොන්", "ද පර්සිස්ටන්ස් ඔෆ් මෙමරි", "1874 පළමු ප්‍රදර්ශනයේදී විචාරකයෙකු මෙම සිතුවමේ නම ඇසුරෙන් උපහාසයට යෙදූ නම පසුව ව්‍යාපාරයේ නම විය."),
        q("උපස්ථිතිවාදී චිත්‍ර ශිල්පීන්ගේ සිතුවම්කරණය පහසු කිරීමට 19 වන සියවසේ සොයා ගැනුණු තාක්ෂණික පහසුකම කුමක්ද?", "ටියුබ්වල ඇසිරූ තෙල් සායම්", "පරිගණක ඩිජිටල් ටැබ්ලට්", "ඇක්‍රිලික් ඉසින බෝතල්", "සිල්ක් ස්ක්‍රීන් මුද්‍රණ යන්ත්‍ර", "ලෝහ ටියුබ්වල තීන්ත ආගමනය නිසා ශිල්පීන්ට එළිමහනට සායම් ගෙන ගොස් ක්ෂණිකව සිතුවම් ඇඳීමට හැකි විය."),
        q("කැමිල් පිසාරෝ (Camille Pissarro) හා ඇල්ෆ්‍රඩ් සිස්ලි (Alfred Sisley) ප්‍රමුඛව සිතුවම් කළ ප්‍රධාන තේමාව කුමක්ද?", "ප්‍රංශ ගම්බද භූ දර්ශන හා ගොවි ජීවිතය", "පුරාණ රෝම යුද සංග්‍රාම", "මිසර රජවරුන්ගේ මමී තැන්පතු", "නූතන අභ්‍යවකාශ යානා", "පිසාරෝ සහ සිස්ලි ස්වභාවික ආලෝකය යටතේ ගම්බද වීදි, ගංගා හා සෘතු වෙනස්කම් සිතුවම් කළහ."),
        q("එඩ්ගා ඩෙගාස් (Edgar Degas) ඔහුගේ බැලේ නර්තන ශිල්පිනියන් සිතුවම් කිරීමේදී තෙල් සායම්වලට අමතරව බහුලව භාවිත කළ මාධ්‍යය කුමක්ද?", "පැස්ටල් කූරු (Pastels)", "ලෝකඩ වාත්තු (Bronze)", "තෙත් හුණු බදාම (Fresco)", "මැටි පුවරු (Terracotta)", "ඩෙගාස් පැස්ටල් මගින් නර්තන ඇඳුම්වල සැහැල්ලු බව හා ක්ෂණික චලනය ඉතා දීප්තිමත්ව නිරූපණය කළේය."),
        q("එඩ්වඩ් මැනේගේ අවසන් මහා කෘතිය වන 'අ බාර් ඇට් ද ෆෝලීස්-බර්ජෙර්' (A Bar at the Folies-Bergère) සිතුවමේ විශේෂත්වය කුමක්ද?", "පසුපස කැඩපතින් පරාවර්තනය වන අමුතු දෘෂ්ටිකෝණය", "සම්පූර්ණයෙන්ම කළු සුදු තිත් පමණක් යෙදීම", "ශිලා පුවරුවක උන්නත කැටයමක් වීම", "සිතුවමේ කිසිදු මිනිස් රූපයක් නොමැති වීම", "පසුබිම් කණ්ණාඩියේ පරාවර්තනය හා සැබෑ පෙනුම වෙනස් කරමින් මැනේ නරඹන්නාට නූතන දෘෂ්ටි ප්‍රශ්නයක් මතු කළේය."),
        q("ජෝර්ජස් සූරා (Georges Seurat) විසින් සිය 'පොයින්ටිලිසම්' තිත් ක්‍රමය යොදා නිර්මාණය කළ දැවැන්ත උද්‍යාන සිතුවම කුමක්ද?", "අ සන්ඩේ ආෆ්ටර්නූන් ඔන් ද අයිලන්ඩ් ඔෆ් ලා ග්‍රෑන්ඩ් ජැටේ", "ද නයිට් කැෆේ ඇට් ආර්ල්ස්", "ද රෙඩ් ස්ටුඩියෝ (The Red Studio)", "ද ග්‍රේට් වේව් ඔෆ් කනගාවා", "මීටර් 3ක් පළල මෙම සිතුවම කුඩා පිරිසිදු වර්ණ තිත් මිලියන ගණනක් එකළඟ තබා නිමවා ඇත."),
        q("සූරා සමඟ 'නව-උපස්ථිතිවාදය' (Neo-Impressionism) සහ වර්ණ විභේදනවාදය (Divisionism) ප්‍රවර්ධනය කළ ප්‍රංශ ශිල්පියා කවුද?", "පෝල් සිග්නැක් (Paul Signac)", "ජෝන් කොන්ස්ටබල් (John Constable)", "ගුස්ටාව් කෝර්බේ (Gustave Courbet)", "ඇන්ටෝනියෝ කැනෝවා (Antonio Canova)", "වර්ණ න්‍යාය විද්‍යාත්මකව අධ්‍යයනය කළ සිග්නැක් වෙරළබඩ දර්ශන විශාල වර්ණ තිත්වලින් සිතුවම් කළේය."),
        q("වින්සන්ට් වෑන් ගෝගේ බොහෝ සිතුවම්වල මතුපිට තීන්ත ඉතා ඝනව, පිහියෙන් හෝ පින්සල් පහරවලින් උස්ව තැන්පත් කර ඇති ශිල්ප ක්‍රමය කුමක්ද?", "ඉම්පැස්ටෝ (Impasto)", "ස්ෆුමාටෝ (Sfumato)", "කියාරෝස්කියුරෝ (Chiaroscuro)", "සිල්වට් (Silhouette)", "ඝනව තැවරූ තීන්ත ස්තර මගින් ආලෝකය පරාවර්තනය වී සිතුවමට අධික ජීවගුණයක් හා රිද්මයක් ලැබේ."),
        q("පෝල් ගොගෑන් (Paul Gauguin) සිය 'කහ ක්‍රිස්තුස්' (The Yellow Christ) වැනි සිතුවම්වල යොදාගත් 'සින්තෙටිසම්' (Synthetism) ශෛලියේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "තද කළු බාහිර රේඛා හා පැතලි වර්ණ තල", "කැඩුණු වීදුරු කැබලි ඇලවීම", "පැන්සලෙන් සියුම් සෙවණැලි ඇඳීම", "වස්තුවල ස්වභාවික ඡායාරූප ගැනීම", "පැරණි වර්ණ වීදුරු ජනෙල් හා ජපන් මුද්‍රණ ආභාසයෙන් ගොගෑන් තද දාර රේඛා තුළ පැතලි වර්ණ පිරවීය."),
        q("1905 පැරිස් ප්‍රදර්ශනයේදී 'ෆෝවිසම්' (Fauvism - වන සතුන්) ව්‍යාපාරයට නායකත්වය දුන් ප්‍රංශ ශිල්පියා කවුද?", "හෙන්රි මැටිස් (Henri Matisse)", "සැල්වදෝර් ඩාලි (Salvador Dalí)", "ජැක්සන් පොලොක් (Jackson Pollock)", "පීට් මොන්ඩ්‍රියන් (Piet Mondrian)", "මැටිස්ගේ 'ද ග්‍රීන් ස්ට්‍රයිප්' හා 'ද රෙඩ් රූම්' සිතුවම් වර්ණය හැඟීම් ප්‍රකාශනයේ ප්‍රධාන මාධ්‍යය බවට පත් කළේය."),
        q("ෆෝවිසම් යුගයේ මැටිස්ගේ සමකාලීන ප්‍රධාන ශිල්පියෙකු වූ 'ඇන්ඩ්‍රේ ඩෙරේන්' (André Derain) ලන්ඩන් පාලම වැනි සිතුවම්වලදී කළ විප්ලවය කුමක්ද?", "සැබෑ වර්ණ වෙනුවට අතිශය දීප්තිමත් වර්ණ යෙදීම", "රත්තරන් තහඩු පමණක් ඇලවීම", "ගල් අඟුරෙන් පමණක් පාලම් ඇඳීම", "වීදුරු බඳුන් මත මල් සිතුවම් කිරීම", "රතු අහස හා කොළ පැහැ මුහුණු වැනි අස්වාභාවික වර්ණ යොදා ෆෝවිසම් ශෛලියේ ප්‍රබල බව පෙන්වීය."),
        q("ජර්මනියේ 'ඩයි බෲක්' (Die Brücke - පාලම) ප්‍රකාශනවාදී කණ්ඩායමේ ආරම්භකයා හා ලී කැටයම් මුද්‍රණ ශිල්පියා කවුද?", "අර්න්ස්ට් ලුඩ්විග් කිර්ච්නර් (Kirchner)", "රෆායෙල් සන්සියෝ (Raphael)", "මයිකල් ආන්ජලෝ (Michelangelo)", "ජියොවානි බෙලිනි (Bellini)", "කිර්ච්නර් නාගරික ජීවිතයේ ආතතිය තියුණු කෝණික රේඛා හා නොගැළපෙන වර්ණවලින් නිරූපණය කළේය."),
        q("'ඩර් බ්ලෝ රයිටර්' (Der Blaue Reiter - නිල් අසරුවා) කණ්ඩායමේ කැන්ඩින්ස්කි සමඟ සම-නිර්මාතෘ වූ, නිල් අශ්වයන් සිතුවම් කළ ශිල්පියා කවුද?", "ෆ්‍රාන්ස් මාර්ක් (Franz Marc)", "ක්ලෝඩ් මොනේ (Claude Monet)", "පියරේ රෙනොයාර් (Renoir)", "ටිෂියන් (Titian)", "සත්ව ලෝකයේ පාරිශුද්ධත්වය දුටු ෆ්‍රාන්ස් මාර්ක් නිල් පැහැය අධ්‍යාත්මිකත්වයේ සංකේතය ලෙස යොදා ගත්තේය."),
        q("වැසිලි කැන්ඩින්ස්කි (Wassily Kandinsky) සිය වියුක්ත සිතුවම්වලට 'Improvisation' හා 'Composition' වැනි නම් යෙදුවේ කුමන කලාව සමඟ සම්බන්ධ කරමින්ද?", "සංගීතය හා නාද රටා", "ගණිතමය භූමි මිනුම්", "පුරාවිද්‍යා කැණීම්", "කෘෂිකාර්මික වගා ක්‍රම", "වර්ණ හා රේඛා මගින් සංගීත භාණ්ඩවල ශබ්දය මෙන් ආත්මීය කම්පනයක් ඇති කළ හැකි බව කැන්ඩින්ස්කි විශ්වාස කළේය."),
        q("පැබ්ලෝ පිකාසෝ 1907 දී ඇඳි, කියුබිසම් කලාවට මග පෑදූ අප්‍රිකානු වෙස්මුහුණු ආභාසය ලත් සුප්‍රකට සිතුවම කුමක්ද?", "ලේස් ඩෙමොයිසෙල්ස් ඩි ඇවිග්නොන්", "ද තර්ඩ් ඔෆ් මේ 1808", "ද ස්කූල් ඔෆ් ඇතැන්ස්", "ද බර්ත් ඔෆ් වීනස්", "කාන්තා රූප පස්දෙනෙකු තියුණු ජ්‍යාමිතික තලවලට කඩා ඇඳි මෙම කෘතිය 20 වන සියවසේ හැරවුම් ලක්ෂ්‍යයකි."),
        q("පැබ්ලෝ පිකාසෝගේ 'රෝස යුගයේ' (Rose Period, 1904–1906) සිතුවම්වල ප්‍රධාන වශයෙන් නිරූපණය වූ තේමාව කුමක්ද?", "සර්කස් ශිල්පීන්, විකටයන් හා උණුසුම් රෝස-තැඹිලි පැහැය", "නිල් පැහැති සාගර කුණාටු හා නැව්", "මධ්‍යකාලීන රජවරුන්ගේ කිරුළු පැළඳීම", "වියුක්ත කළු කොටු පමණි", "දුක්මුසු නිල් යුගයෙන් පසු රෝස යුගයේදී පිකාසෝ සංචාරක සර්කස් පවුල් උණුසුම් වර්ණවලින් ඇන්දේය."),
        q("ජෝර්ජස් බ්‍රාක් (Georges Braque) සමඟ කියුබිසම් සංවර්ධනය කිරීමේදී පිකාසෝ 'කොලාජ්' (Collage) තාක්ෂණයට එක් කළ ද්‍රව්‍ය මොනවාද?", "පුවත්පත් කැබලි, බිතුපත් හා රෙදි", "රත්තරන් පත්‍ර හා ඇත්දත් කැබලි", "තෙත් මැටි හා හුණු ගල් කුඩු", "ජල සායම් හා මී ඉටි පමණි", "සැබෑ ජීවිතයේ කඩදාසි කැබලි සෘජුවම කැන්වසය මත ඇලවීමෙන් 'කොලාජ්' කලාව නූතන චිත්‍රයට එක් විය."),
        q("කියුබිසම් කලාවෙන් බිහි වූ ප්‍රංශ ශිල්පී 'ෆර්නෑන්ඩ් ලෙජර්' (Fernand Léger) ඔහුගේ සිතුවම්වල මිනිස් රූප නිර්මාණය කළේ කෙසේද?", "නළ, සිලින්ඩර හා යන්ත්‍ර කොටස් වැනි හැඩවලින්", "සියුම් ලියවැල් හා මල් රටාවලින්", "අඳුරු සෙවණැලි රේඛා පමණක් යොදා", "සත්ව හිස් හා කුරුලු පියාපත් එක්කර", "නූතන කාර්මික යුගය වර්ණනා කළ ලෙජර්ගේ ශෛලිය 'ටියුබිසම්' (Tubism) ලෙසද හැඳින්වේ."),
        q("ඉතාලි ෆියුචරිසම් (Futurism) ව්‍යාපාරයේ උම්බර්ටෝ බොචියෝනි (Umberto Boccioni) නිර්මාණය කළ සුප්‍රකට චලන මූර්තිය කුමක්ද?", "යුනික් ෆෝම්ස් ඔෆ් කන්ටිනියුටි ඉන් ස්පේස්", "ද තින්කර් (The Thinker)", "ඩේවිඩ් (David)", "ද කිස් (The Kiss)", "වේගයෙන් ඉදිරියට ඇවිදින මානව රූපයක ගතික වේගය දිලිසෙන ලෝකඩ මූර්තියකින් මෙහි නිරූපිතය."),
        q("ඩාඩා (Dada) ව්‍යාපාරයේ මාර්සෙල් ඩුෂෑම්ප් (Marcel Duchamp) 1917 දී පිඟන් මැටි මුත්‍රා බඳුනක් ප්‍රදර්ශනයට තබා හඳුන්වා දුන් කලා සංකල්පය කුමක්ද?", "රෙඩිමේඩ් (Readymade)", "ට්‍රොම්ප් ලොයිල් (Trompe l'oeil)", "චියාරොස්කියුරෝ (Chiaroscuro)", "සෝල්ට් ග්ලේස් (Salt Glaze)", "සාමාන්‍ය කර්මාන්තශාලා භාණ්ඩයක් කලාකරුගේ තේරීම හා අදහස මත කලා කෘතියක් වන බව 'රෙඩිමේඩ්' මගින් පෙන්වීය."),
        q("මාර්සෙල් ඩුෂෑම්ප්ගේ 1912 සුප්‍රකට සිතුවම වන 'Nude Descending a Staircase, No. 2' තුළ දැකිය හැකි ප්‍රධාන ලක්ෂණය කුමක්ද?", "පඩිපෙළ බසින රූපයක අනුක්‍රමික චලන රාමු එකවර පෙන්වීම", "පඩිපෙළක් උඩ නිදා සිටින නිශ්චල සිංහයෙකු", "මුහුදු රළ මත පාවෙන ධීවර බෝට්ටුවක්", "ග්‍රීක දෙවොලක සම්භාව්‍ය කුළුණු පෙළක්", "කියුබිසම් හා ෆියුචරිසම් එක් කරමින් ඡායාරූප චලන රාමු මෙන් කාලය හා චලනය මෙහි නිරූපණය කර ඇත."),
        q("පළමු ලෝක යුද්ධය අතරතුර 'ඩාඩා' ව්‍යාපාරයේ හා පසුව සරියලිසම්හි පුරෝගාමියෙකු වූ 'මෑන් රේ' (Man Ray) කැපී පෙනුණේ කුමන කලාවෙන්ද?", "පරීක්ෂණාත්මක ඡායාරූප හා රේයෝග්‍රෑම් (Rayographs)", "සාම්ප්‍රදායික ගල් කැටයම්", "තෙත් හුණු බදාම විහාර සිතුවම්", "පෝසිලේන් මල් බඳුන් නිෂ්පාදනය", "කැමරාවක් නොමැතිව ඡායාරූප කඩදාසි මත වස්තූන් තබා ආලෝකය යවා 'රේයෝග්‍රෑම්' නමැති කලා ඡායාරූප නිමැවීය."),
        q("සරියලිසම් (Surrealism) ව්‍යාපාරයේ 'සිහින දැක්ම' ශෛලියට වෙනස්ව, සරල හා කුඩා ජීව විද්‍යාත්මක සංකේතවලින් සිතුවම් කළ ස්පාඤ්ඤ ශිල්පියා කවුද?", "ජෝන් මිරෝ (Joan Miró)", "පීටර් පෝල් රූබන්ස් (Rubens)", "ජැක් ලුවී ඩේවිඩ් (David)", "ෆ්‍රැන්සිස්කෝ ගෝයා (Goya)", "මිරෝ ඉර, හඳ, තරු හා සරල රේඛා යොදා ළමා සිතුවම් මෙන් නිදහස් උපවිඥානික සිතුවම් නිර්මාණය කළේය."),
        q("පීට් මොන්ඩ්‍රියන්ගේ (Piet Mondrian) 'නියෝප්ලාස්ටිසිසම්' (Neoplasticism) චිත්‍රවල දක්නට ලැබෙන වර්ණ සංයෝජනය කුමක්ද?", "රතු, නිල්, කහ හා කළු, සුදු, අළු", "දම්, තැඹිලි, දුඹුරු හා රන්වන්", "කොළ, රෝස, අහස් නිල් හා රිදී", "තනි ලා කොළ පැහැ ප්‍රභේද පමණි", "මූලික වර්ණ තුන හා අවර්ණ තුන පමණක් සෘජුකෝණාස්‍රවලට යොදා පරම සමතුලිතතාව සෙවීම මොන්ඩ්‍රියන්ගේ ඉලක්කය විය."),
        q("රේඛීය ජ්‍යාමිතිය හා ක්‍රියාකාරී සරල බව අගය කළ ජර්මානු 'බවුහවුස්' (Bauhaus) පාසලේ සුප්‍රකට නිර්මාණ මූලධර්මය කුමක්ද?", "ස්වරූපය කාර්යය අනුගමනය කරයි (Form follows function)", "සැරසිලි වැඩි වන තරමට ගෘහය අලංකාර වේ", "පුරාණ ග්‍රීක කුළුණු සෑම ගොඩනැගිල්ලකම තිබිය යුතුය", "සියලු භාණ්ඩ අතින් පමණක් කැටයම් කළ යුතුය", "කලාව හා කාර්මික නිෂ්පාදනය එක් කළ බවුහවුස් පාසල නූතන ගෘහ නිර්මාණ හා ග්‍රැෆික් කලාව හැඩගැස්වීය."),
        q("ඇමරිකානු වියුක්ත ප්‍රකාශනවාදයේ (Abstract Expressionism) ප්‍රධාන පුරෝගාමියෙකු වූ 'විලෙම් ද කූනිං' (Willem de Kooning) වඩාත් ප්‍රසිද්ධ වූ සිතුවම් මාලාව කුමක්ද?", "විමෙන් (Woman I–VI) මාලාව", "ලිලී මල් පොකුණ මාලාව", "පිදුරු ගොඩවල් මාලාව", "රාජකීය පවුලේ ආලේඛ්‍ය මාලාව", "වේගවත් රළු පින්සල් පහරවල් මගින් විකෘති කළ කාන්තා රූප ඔහුගේ වියුක්ත ප්‍රකාශනවාදයේ ලක්ෂණයකි."),
        q("රෙදි හා කැන්වසය මත කෙළින්ම දියර සායම් කාන්දු කර (Stain painting) වර්ණ ක්ෂේත්‍ර මැවූ කාන්තා වියුක්ත ප්‍රකාශනවාදී ශිල්පිනිය කවුද?", "හෙලන් ෆ්‍රැන්කෙන්තාලර් (Helen Frankenthaler)", "සොෆොනිස්බා ඇන්ගුයිසෝලා", "ආටෙමිසියා ජෙන්ටිලෙස්කි", "විජී ලෙ බෘන් (Vigée Le Brun)", "ඇයගේ 'සෝක්-ස්ටේන්' (Soak-stain) තාක්ෂණය වර්ණ ක්ෂේත්‍ර චිත්‍ර කලාවේ (Color Field Painting) නව මගක් විවර කළේය."),
        q("කැන්වසයේ පිළිවෙළට ඇඳි වර්ණවත් තීරු හෝ සංකේන්ද්‍රීය වෘත්ත යොදාගත් ඇමරිකානු 'හාඩ්-එජ්' (Hard-Edge) සහ Color Field ශිල්පියා කවුද?", "කෙනත් නෝලන්ඩ් (Kenneth Noland)", "රෙම්බ්‍රාන්ඩ් (Rembrandt)", "කරවැජියෝ (Caravaggio)", "වර්මියර් (Vermeer)", "වර්ණ තල අතර හැඟීම් ප්‍රකාශන බුරුසු පහරවල් ඉවත් කර පැහැදිලි දාර සහිත ජ්‍යාමිතික වර්ණ රටා ඔහු නිර්මාණය කළේය."),
        q("1960 දශකයේ බ්‍රිතාන්‍ය හා ඇමරිකානු 'පොප් ආර්ට්' (Pop Art) ශිල්පී රෝයි ලික්ටෙන්ස්ටයින් (Roy Lichtenstein) සිය සිතුවම් සඳහා ආභාසය ගත්තේ කුමකින්ද?", "විකට චිත්‍ර කතා (Comic strips) හා බෙන්-ඩේ තිත්", "පුරාණ චීන පෝසිලේන් බඳුන්", "මධ්‍යකාලීන රන් ආලේපිත පොත්", "අප්‍රිකානු ගෝත්‍රික දැව වෙස්මුහුණු", "මුද්‍රණ කලාවේ බෙන්-ඩේ තිත් (Ben-Day dots) හා කථන බුබුළු විශාල කැන්වස් මත සිතුවම් කිරීම ඔහුගේ ශෛලියයි."),
        q("පොප් ආර්ට් ව්‍යාපාරයේ පුරෝගාමී බ්‍රිතාන්‍ය චිත්‍ර ශිල්පී 'රිචඩ් හැමිල්ටන්' (Richard Hamilton) 1956 දී නිමැවූ සුප්‍රකට කොලාජ් කෘතිය කුමක්ද?", "ජස්ට් වොට් ඉස් ඉට් දැට් මේක්ස්...", "ද ලාස්ට් සපර් (The Last Supper)", "ද නයිට් වොච් (The Night Watch)", "ගර්නිකා (Guernica - Picasso)", "වෙළෙඳ දැන්වීම් හා සඟරා කැබලි එක්කර නිමැවූ මෙම කෘතිය පොප් ආර්ට් හි පළමු ප්‍රධාන සංධිස්ථානය ලෙස සැලකේ."),
        q("ඩේවිඩ් හොක්නි (David Hockney) ලොස් ඇන්ජලීස්හි පිහිනුම් තටාක හා කැලිෆෝනියානු ආලෝකය නිරූපණය කරමින් 1967 දී ඇඳි ප්‍රකට සිතුවම කුමක්ද?", "අ බිගර් ස්ප්ලෑෂ් (A Bigger Splash)", "සන්ෆ්ලවර්ස් (Sunflowers)", "ද වේව් (The Wave)", "සන්ඩේ ඉන් ද පාර්ක්", "ඇක්‍රිලික් තීන්ත යොදා පැතලි වර්ණ තල හා ජල බිඳු විසිරීම දැක්වූ මෙම සිතුවම බ්‍රිතාන්‍ය පොප් කලාවේ මුදුන්මල්කඩකි."),
        q("දෘෂ්ටි මායාවන් මවන 'ඔප් ආර්ට්' (Op Art) කලාවේ ප්‍රධාන කාන්තා පුරෝගාමියා වන බ්‍රිතාන්‍ය ශිල්පිනිය කවුද?", "බ්‍රිජට් රයිලි (Bridget Riley)", "මේරි කැසැට් (Mary Cassatt)", "ජෝර්ජියා ඕ'කීෆ් (O'Keeffe)", "තමාරා ඩි ලෙම්පිකා", "කළු-සුදු රැලි රේඛා හා ජ්‍යාමිතික රටා මගින් ඇසට චලනය වන සේ දැනෙන දෘෂ්ටි මායා රයිලි නිර්මාණය කළාය."),
        q("මෝල් හා මල්වල විශාලනය කළ සමීප රූප හා නිව් මෙක්සිකෝ කාන්තාර ඇටකටු සිතුවම් කළ ඇමරිකානු නූතන චිත්‍ර ශිල්පිනිය කවුද?", "ජෝර්ජියා ඕ'කීෆ් (Georgia O'Keeffe)", "බර්ත් මොරිසෝ (Berthe Morisot)", "රෝසා බොන්හර් (Rosa Bonheur)", "කැතේ කොල්විට්ස් (Käthe Kollwitz)", "ස්වභාවධර්මයේ සියුම් හැඩතල වියුක්ත ආකාරයට විශාල කොට ඇඳීම ඇමරිකානු නූතනවාදයේ ඇගේ අනන්‍යතාවයි."),
        q("බ්‍රිතාන්‍ය මූර්ති ශිල්පිනී 'බාබරා හෙප්වර්ත්' (Barbara Hepworth) හෙන්රි මුවර් සමඟ එක්ව නූතන මූර්ති කලාවට දුන් දායකත්වය කුමක්ද?", "දැව හා ගල්වල සිදුරු සහිත ඓන්ද්‍රීය වියුක්ත හැඩතල", "රජවරුන්ගේ අශ්වාරෝහක ප්‍රතිමා", "පෝසිලේන් තේ කෝප්ප කට්ටල", "ග්‍රීක දේව ප්‍රතිමා පිටපත් කිරීම", "මූර්තියේ අභ්‍යන්තර අවකාශය හා තන්තු සම්බන්ධ කරමින් භූ දර්ශනය හා බැඳුණු වියුක්ත මූර්ති ඇය නිමැවූවාය."),
        q("නූතන ගෘහ නිර්මාණ ශිල්පී 'ලේ කොර්බුසියේ' (Le Corbusier) සහ 'ෆ්‍රෑන්ක් ලොයිඩ් රයිට්' (Frank Lloyd Wright) කුමන කලා ක්ෂේත්‍රයේ පුරෝගාමීන්ද?", "20 වන සියවසේ නූතන ගෘහ නිර්මාණ ශිල්පය", "ජපන් උකියෝ-ඒ ලී කැටයම් මුද්‍රණය", "ඉන්දියානු මූගල් කුඩා සිතුවම්", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ සෑදීම", "කොන්ක්‍රීට්, වීදුරු හා පරිසරයට ගැළපෙන ඓන්ද්‍රීය ගොඩනැගිලි මොවුන් ලොවට හඳුන්වා දුන්හ."),
        q("නිව්යෝර්ක් නගරයේ 1980 දශකයේදී සරල හාස්‍යජනක රූප හා නර්තන හැඩතල උමං දුම්රිය බිත්තිවල ඇඳි පොප්-ග්‍රැෆිටි ශිල්පියා කවුද?", "කීත් හැරින් (Keith Haring)", "රෆායෙල් (Raphael)", "ගුස්ටාව් ක්ලිම්ට් (Gustav Klimt)", "තියඩෝර් ජෙරිකෝ (Géricault)", "ඝන කළු බාහිර රේඛා හා දීප්තිමත් වර්ණවලින් යුත් මානව රූප මගින් කීත් හැරින් සමාජ පණිවිඩ ඉදිරිපත් කළේය."),
        q("නූතන 'ලෑන්ඩ් ආර්ට්' (Land Art / Earthworks) කලා ව්‍යාපාරයේ ශිල්පීන් සිය කලා කෘති නිර්මාණය කරන්නේ කුමන මාධ්‍යය යොදාගෙනද?", "පස්, ගල්, වැලි හා ස්වාභාවික භූමිය", "කෞතුකාගාරවල වීදුරු රාමු", "රන් හා රිදී පමණක්", "කඩදාසි මත ජල සායම්", "රොබට් ස්මිත්සන්ගේ 'ස්පයිරල් ජෙටි' මෙන් ස්වාභාවික පරිසරයම කලා කෘතියක් ලෙස මෙහිදී සැකසේ."),
        q("1960 දශකයේ ජනප්‍රිය වූ 'මිනිමලිසම්' (Minimalism) කලා ව්‍යාපාරයේ ප්‍රධානතම ලක්ෂණය කුමක්ද?", "අතිශය සරල ජ්‍යාමිතික හැඩ හා කාර්මික ද්‍රව්‍ය යෙදීම", "රජ මාලිගාවල සංකීර්ණ ජන කතා සිතුවම් කිරීම", "මිනිස් මුහුණුවල සියුම් ඉරියව් යථාර්ථවාදීව ඇඳීම", "වර්ණ සිය ගණනක් එකට මිශ්‍ර කර පොදි ගැසීම", "ඩොනල්ඩ් ජඩ් හා ඩෑන් ෆ්ලේවින් වැනි ශිල්පීන් ශිල්පියාගේ හැඟීම් ප්‍රකාශනය ඉවත් කර පිරිසිදු හැඩ මතු කළහ."),
        q("බැරොක් හා යථාර්ථවාදී ආර ඉක්මවා 19 වන සියවසේ ප්‍රංශයේ 'රියලිසම්' (Realism) ව්‍යාපාරයෙන් ගුස්ටාව් කෝර්බේ සිතුවම් කළේ කවුරුන්ද?", "සාමාන්‍ය කම්කරුවන් හා ගල් කඩන්නන්", "සුරඟනන් හා පියාඹන දේවදූතයන්", "ග්‍රීක ඔලිම්පස් කන්දේ දෙවිවරුන්", "පුරාණ මිසර පාරාවෝ රජවරුන්", "මිථ්‍යා හෝ රාජකීය පුද්ගලයන් වෙනුවට එදිනෙදා වැඩකරන ජනතාව ගෞරවයෙන් ඇඳීම රියලිසම්හි ආරම්භයයි."),
        q("වියානා සෙසෙෂන් (Vienna Secession) ව්‍යාපාරයේ නායකත්වය දැරූ, 'ද කිස්' (The Kiss) සිතුවමට රන් පත්‍ර යෙදූ ඔස්ට්‍රියානු ශිල්පියා කවුද?", "ගුස්ටාව් ක්ලිම්ට් (Gustav Klimt)", "ඇන්ඩි වෝහෝල් (Andy Warhol)", "ජෝර්ජස් සූරා (Seurat)", "හෙන්රි මුවර් (Henry Moore)", "රන් පත්‍ර හා සංකීර්ණ මෝස්තර රටා යෙදූ ක්ලිම්ට්ගේ කලාව 'ආර්ට් නුවෝ' (Art Nouveau) සමඟ සමීපව බැඳේ."),
        q("පිකාසෝ හා මැටිස් සමඟ අනුරූපව 'මොඩිග්ලියානි' (Amedeo Modigliani) ඇඳි ආලේඛ්‍ය සිතුවම්වල විශේෂිත රූපමය ලක්ෂණය කුමක්ද?", "දිගැති මුහුණු, දිගු බෙල්ල හා ආමන්ඩ් හැඩැති ඇස්", "අතිශය කෙටි මිටි ශරීර හා හතරැස් හිස්", "මුහුණ වෙනුවට පලතුරු හා මල් ඇඳීම", "වර්ණ තිත් පමණක් යොදා බොඳ කිරීම", "අප්‍රිකානු වෙස්මුහුණු ආභාසයෙන් මොඩිග්ලියානි අනන්‍ය වූ සරල දිගැති මානව රූප නිර්මාණය කළේය."),
        q("සැබෑ වස්තූන් විකෘති කර සිහින හා ගැමි මතකයන් පාවෙන රූප ලෙස ඇඳි රුසියානු-ප්‍රංශ නූතන ශිල්පියා කවුද?", "මාර්ක් ෂගාල් (Marc Chagall)", "ජෝන් කොන්ස්ටබල් (Constable)", "ටර්නර් (J.M.W. Turner)", "ජෝසුවා රෙනෝල්ඩ්ස් (Reynolds)", "අහසේ පාවෙන පෙම්වතුන්, වයලීන වාදකයන් හා එළුවන් සිතුවම් කළ ෂගාල්ගේ කලාව සරියලිසම්ට පූර්වාදර්ශයක් විය."),
        q("නූතන චිත්‍ර කලාවට 'ෆොටෝමොන්ටාජ්' (Photomontage) හෙවත් ඡායාරූප කැබලි කපා එකතු කර දේශපාලන උපහාස නිමැවූ ඩාඩා ශිල්පිනිය කවුද?", "හැනා හොච් (Hannah Höch)", "සොනියා ඩෙලෝනේ (Sonia Delaunay)", "මාරිනා අබ්‍රමොවිච්", "යයෝයි කුසාමා", "සඟරා ඡායාරූප කපා නව අර්ථ මවමින් ඇය වයිමාර් ජර්මනියේ සමාජ වෙනස්කම් විවේචනය කළාය."),
        q("පැහැදිලි දෘෂ්ටි රූප වෙනුවට කේන්ද්‍රීය වෘත්ත හා වර්ණ තරංග යොදා 'ඔර්ෆිසම්' (Orphism) ආරම්භ කළ යුවළ කවුද?", "රොබට් සහ සොනියා ඩෙලෝනේ", "පිකාසෝ සහ ජෝර්ජස් බ්‍රාක්", "ඩාලි සහ රෙනේ මැග්‍රිට්", "මොනේ සහ පියරේ රෙනොයාර්", "කියුබිසම් ව්‍යුහයට වර්ණවත් රිද්මය හා ආලෝකය එක් කිරීමෙන් මොවුන් වියුක්ත කලාව ඉදිරියට ගෙන ගියහ."),
        q("සරියලිසම්හි පරිකල්පනය 'ලෝහමය හෝ ඝන මානව හිස් හා සිරුරු' වෙනුවට පාරිසරික අභිරහස් චතුරශ්‍ර නගර ලෙස ඇඳි ඉතාලි පූර්වගාමියා කවුද?", "ජෝර්ජියෝ ඩි චිරිකෝ (Giorgio de Chirico)", "ලියනාඩෝ ඩා වින්චි", "සැන්ඩ්‍රෝ බොටිචෙලි", "පාවුලෝ වෙරොනීස්", "ඔහුගේ හිස් නගර චතුරශ්‍ර හා දිගු සෙවණැලි සහිත 'මෙටාෆිසිකල්' සිතුවම් සරියලිසම් ශිල්පීන්ට මග පෙන්වීය."),
        q("ඇමරිකානු 'ඇෂ්කෑන් පාසල' (Ashcan School) සහ 'එඩ්වඩ් හොපර්' (Edward Hopper) සිතුවම් කළේ කුමන තේමාවක්ද?", "නූතන නගර ජීවිතයේ හුදෙකලාව හා එදිනෙදා අවන්හල්", "පුරාණ ග්‍රීක ඔලිම්පික් තරග", "මධ්‍යකාලීන රාජ සභා උත්සව", "රෝම අධිරාජ්‍යයේ යුද ජයග්‍රහණ", "හොපර්ගේ 'නයිට්හෝක්ස්' (Nighthawks) රාත්‍රී අවන්හල් සිතුවම නූතන නාගරික හුදෙකලාව කැපී පෙනෙන ලෙස දක්වයි."),
        q("නවීන 'වර්ණ ක්ෂේත්‍ර' (Color Field) ශිල්පී බාර්නෙට් නිව්මන්ගේ (Barnett Newman) විශාල තනි වර්ණ සිතුවම් මැදින් යන සිරස් ඉරි හඳුන්වන්නේ කුමන නමින්ද?", "සිප්ස් (Zips)", "ඩොට්ස් (Dots)", "මොබයිල්ස් (Mobiles)", "ෆ්‍රෙස්කෝස් (Frescos)", "ප්‍රේක්ෂකයා තුළ ආධ්‍යාත්මික නිහඬ බවක් ඇති කිරීමට විශාල වර්ණ පසුබිමක මෙම සිරස් රේඛා යොදා ඇත."),
        q("ගතික චිත්‍ර ශිල්පයේදී (Action Painting) බුරුසුව කැන්වසයේ නොගාවා තීන්ත විසි කිරීමට 'ජැක්සන් පොලොක්' අමතරව භාවිත කළ ද්‍රව්‍යය කුමක්ද?", "ලී කෝටු, හැඳි සහ සිදුරු කළ තීන්ත ටින්", "පිහාටු පෑන් හා කළු ගල් අඟුරු", "සාම්ප්‍රදායික ගල් කටු හා මිටි", "කඩදාසි කතුරු හා මැලියම් පමණි", "සාම්ප්‍රදායික චිත්‍ර පුවරුව (Easel) ඉවත දමා බිම එළූ කැන්වසය වටා ඇවිදිමින් ඔහු සිතුවම් කළේය."),
        q("ලොව ප්‍රකට 'සුපිරි විශාල මූර්ති' හා 'ස්ටේන්ලස් ස්ටීල්' පරාවර්තක කලා කෘති (Cloud Gate) නිමවන ඉන්දීය සම්භවයක් ඇති නූතන මූර්ති ශිල්පියා කවුද?", "අනිෂ් කපූර් (Anish Kapoor)", "ඔගස්ට් රොඩින් (Auguste Rodin)", "දොනතෙල්ලෝ (Donatello)", "බෙනවෙනුටෝ සෙලිනි (Cellini)", "දර්පණ මෙන් පරිසරය පරාවර්තනය කරන අනිෂ් කපූර්ගේ නූතන පොදු අවකාශ මූර්ති ඉතා ප්‍රසිද්ධය."),
        q("ජපානයේ සමකාලීන කලාකාරිනී 'යයෝයි කුසාමා' (Yayoi Kusama) ගේ කලා කෘති හඳුනා ගැනීමේ ප්‍රධාන දෘශ්‍ය ලක්ෂණය කුමක්ද?", "පුනරාවර්තන පොල්කා තිත් (Polka dots) හා කණ්ණාඩි කාමර", "දැව කැටයම් බුදු පිළිම පමණක් නෙළීම", "තෙත් හුණු බදාම ශෛලියෙන් මාලිගා ඇඳීම", "වර්ණ රහිත අළු රේඛා සටහන් පමණි", "අනන්ත කණ්ණාඩි කාමර හා වට්ටක්කා මූර්ති තුළ ඇගේ අනන්‍ය පොල්කා තිත් රටා ලොව පුරා ප්‍රකටය."),
        q("20 වන සියවසේ සුප්‍රකට 'පර්ෆෝමන්ස් ආර්ට්' (Performance Art - රංගන කලාව) හිදී කලා කෘතියේ ප්‍රධාන මාධ්‍යය වන්නේ කුමක්ද?", "කලාකරුගේම ශරීරය හා සජීවී ක්‍රියාකාරකම", "කිරිගරුඬ හා කළුගල් කුට්ටි", "තඹ තහඩු මත ඇසිඩ් මුද්‍රණය", "රෙදි හා නූල්වලින් මැසූ බැනර්", "කැන්වසය හෝ ගල වෙනුවට සජීවී කාලය, අවකාශය හා කලාකරුගේ සිරුර කලා මාධ්‍යය ලෙස මෙහිදී භාවිත කෙරේ."),
        q("රේමන්ඩ් කැරිංටන් හා ප්‍රංශ ශිල්පී 'හෙන්රි රූසෝ' (Henri Rousseau) අනුගමනය කළ ස්වයං-ඉගෙනුම් සරල කලා ආර කෙසේ හැඳින්වේද?", "නායිව් ආර්ට් (Naive Art - සරල/ප්‍රාථමික කලාව)", "හයි රෙනේසන්ස් (High Renaissance)", "නියෝ ක්ලැසිසම් (Neoclassicism)", "ගොතික් වාස්තු කලාව (Gothic)", "විධිමත් ඇකඩමික් පුහුණුවක් නොලැබුවද වනාන්තර හා සිහින ලෝක ඉතා නිර්මාණශීලීව රූසෝ සිතුවම් කළේය.")
    )
}
